from typing import List


def process_intents(commands: List[str]) -> List[str]:
    merchants = {}  # mid -> [balance, refund_limit]，limit 为 None 表示不限时
    intents = {}    # pid -> {"mid", "amt", "state", "refunded", "succeed_ts"}
    for cmd in commands:
        p = cmd.split()
        ts, op = int(p[0]), p[1]
        if op == "INIT":
            mid, bal = p[2], int(p[3])
            limit = int(p[4]) if len(p) >= 5 else None
            if limit is not None and limit < 0:
                limit = None                    # 负数等同于不限时
            if mid not in merchants:
                merchants[mid] = [bal, limit]
        elif op == "CREATE":
            pid, mid, amt = p[2], p[3], int(p[4])
            if pid in intents or mid not in merchants or amt < 0:
                continue
            intents[pid] = {"mid": mid, "amt": amt, "state": "REQUIRES_ACTION",
                            "refunded": False, "succeed_ts": None}
        else:
            it = intents.get(p[2])
            if it is None:
                continue
            if op == "UPDATE":
                if it["state"] == "REQUIRES_ACTION" and int(p[3]) >= 0:
                    it["amt"] = int(p[3])
            elif op == "ATTEMPT":
                if it["state"] == "REQUIRES_ACTION":
                    it["state"] = "PROCESSING"
            elif op == "SUCCEED":
                if it["state"] == "PROCESSING":
                    it["state"] = "COMPLETED"
                    it["succeed_ts"] = ts
                    merchants[it["mid"]][0] += it["amt"]
            elif op == "FAIL":
                if it["state"] == "PROCESSING":
                    it["state"] = "REQUIRES_ACTION"
            elif op == "REFUND":
                if it["state"] != "COMPLETED" or it["refunded"]:
                    continue
                m = merchants[it["mid"]]
                limit = m[1]
                if limit is not None and ts > it["succeed_ts"] + limit:
                    continue                    # limit = 0 时任何 ts > succeed_ts 都被拒
                m[0] -= it["amt"]
                it["refunded"] = True
    return [f"{mid} {merchants[mid][0]}" for mid in sorted(merchants)]
